PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT, google_sub TEXT UNIQUE, verified INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, settings TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,admin_id TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,CHECK((user_id IS NOT NULL) != (admin_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY,subject TEXT NOT NULL,purpose TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS challenge_subject ON challenges(subject,purpose,created_at);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,hits INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id TEXT PRIMARY KEY,name TEXT NOT NULL,price INTEGER NOT NULL,daily_limit INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,plan_id TEXT NOT NULL REFERENCES plans(id),amount INTEGER NOT NULL CHECK(amount>0),utr TEXT NOT NULL UNIQUE COLLATE NOCASE,payer_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')),submitted_at INTEGER NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,review_note TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_per_user ON payments(user_id) WHERE status='PENDING';
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,plan_id TEXT NOT NULL REFERENCES plans(id),activated_at INTEGER NOT NULL,expires_at INTEGER,source_payment TEXT UNIQUE REFERENCES payments(id),CHECK((plan_id='lifetime' AND expires_at IS NULL) OR (plan_id!='lifetime' AND expires_at IS NOT NULL)));
CREATE TRIGGER IF NOT EXISTS preserve_lifetime BEFORE UPDATE ON memberships WHEN OLD.plan_id='lifetime' AND (NEW.plan_id!='lifetime' OR NEW.expires_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Lifetime membership cannot expire or downgrade'); END;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chats (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,title TEXT NOT NULL,model TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS chats_user ON chats(user_id,updated_at);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,model TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS messages_chat ON messages(chat_id,created_at);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,storage_key TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS saved_prompts (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,text TEXT NOT NULL,category TEXT NOT NULL,favorite INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS usage (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,model TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'reserved',created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS usage_user_date ON usage(user_id,created_at);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,published_at INTEGER NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS health_samples (id INTEGER PRIMARY KEY AUTOINCREMENT,service TEXT NOT NULL,status TEXT NOT NULL,latency_ms INTEGER,checked_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS health_service_date ON health_samples(service,checked_at);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,created_at INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_version VALUES(1,unixepoch()*1000);
